// DeepBench v7.0.463 | tests/regression/ses-377-cycle-card.test.mjs | SES-377
//
// FEATURE: SES-377 -- docs/runbooks/cycle-card.md, a 5-10 KB executable digest of the 363,840-byte
// docs/runbooks/runner-cycle.md, GENERATED by scripts/render-cycle-card.js and never hand-written.
//
// WHAT THIS FILE IS ACTUALLY GUARDING, and it is not "the card exists". ARCHITECTURE.md §19v says
// the runbook is the ONE home of the procedure; a second copy of an executable procedure drifts
// silently and then one of them is wrong (check-session-docs.js check 13 says the same thing in
// code). The card is admissible only because it is a VIEW: rendered from the runbook, and held
// equal to a fresh render by this test on every suite run. Arm (A) is therefore the load-bearing
// one -- it is the entire justification for SES-377's PROCEDURE_GENERATED_DOCS exemption, which
// arm (G) pins to the same path. Edit the runbook and forget to re-render and the suite goes red;
// hand-edit the card and the suite goes red. That is the whole contract.
//
// SOURCE-ONLY, ALWAYS RUNS. No credentials, no network, no Supabase -- two files, one import and
// one spawn of the CLI. Every arm that could pass vacuously carries a negative control that must
// go RED on the mutation (the SES-158 failure: a control that changes nothing pins nothing).

import fs from "node:fs";
import path from "node:path";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { selfRun } from "./_lib/self-run.js";
import {
  render,
  parseSteps,
  parseBlocks,
  blocksByStep,
  runbookSha,
  NOTES,
  FULL_BLOCK_MAX,
  CARD_BYTE_CAP,
  CARD_REL,
  RUNBOOK_REL,
} from "../../scripts/render-cycle-card.js";
import { PROCEDURE_GENERATED_DOCS } from "../../scripts/check-session-docs.js";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const CARD_MIN = 5120;
const SCRIPT_REL = "scripts/render-cycle-card.js";

const readLf = rel => fs.readFileSync(path.join(ROOT, rel), "utf8").replace(/\r\n/g, "\n");

// A card step line: `**<label>.** <title> · L<n> · <outcome> · blocks: L<n>(<lang> <n>B) …`,
// optionally followed by the one fenced block that step carries in full.
export function parseCard(card) {
  const lines = card.split("\n");
  const out = [];
  for (let i = 0; i < lines.length; i++) {
    const m = /^\*\*([0-9a-z-]+)\.\*\* (.*)$/.exec(lines[i]);
    if (!m) continue;
    const entry = {
      label: m[1],
      at: i + 1,
      text: m[2],
      anchors: [...m[2].matchAll(/L(\d+)\((\S+) (\d+)B\)/g)].map(a => Number(a[1])),
      fence: null,
    };
    // The block, when shown, is the next non-blank thing under the line.
    let j = i + 1;
    while (j < lines.length && lines[j] === "") j++;
    const open = j < lines.length ? /^```([a-z]*)\s*$/.exec(lines[j]) : null;
    if (open) {
      let k = j + 1;
      while (k < lines.length && !/^```\s*$/.test(lines[k])) k++;
      entry.fence = { lang: open[1], body: lines.slice(j + 1, k).join("\n") };
    }
    out.push(entry);
  }
  return out;
}

// (B) Every runbook step is a card line, in runbook order, and no card line is anything else.
export function everyStepIsOnTheCard(card, md) {
  const steps = parseSteps(md).map(s => s.label);
  const onCard = parseCard(card).map(c => c.label);
  assert.ok(steps.length > 0, `${RUNBOOK_REL} parsed to 0 steps`);
  assert.deepStrictEqual(
    onCard,
    steps,
    `${CARD_REL}'s step labels must be exactly ${RUNBOOK_REL}'s, in runbook order. ` +
      "A missing label is a step a cycle never executes; an extra one is a step that does not exist.",
  );
}

// (C) Every fenced block on the card is the runbook's own bytes, at an L-anchor the card names.
export function everyCardBlockIsTheRunbooksBytes(card, md) {
  const steps = parseSteps(md);
  const by = blocksByStep(steps, parseBlocks(md));
  let shown = 0;
  for (const line of parseCard(card)) {
    const note = NOTES[line.label];
    assert.ok(note, `${CARD_REL} line ${line.at}: step **${line.label}.** has no NOTES entry`);
    const blocks = by.get(line.label) || [];
    const chosen = note.block > 0 ? blocks[note.block - 1] : null;
    const expected = chosen && Buffer.byteLength(chosen.body, "utf8") <= FULL_BLOCK_MAX ? chosen : null;

    if (!expected) {
      assert.strictEqual(
        line.fence,
        null,
        `${CARD_REL} line ${line.at}: step **${line.label}.** carries a fenced block, but its ` +
          "selected block is absent or over FULL_BLOCK_MAX and must render as a pointer.",
      );
      continue;
    }
    assert.ok(line.fence, `${CARD_REL} line ${line.at}: step **${line.label}.** must carry its block in full (${Buffer.byteLength(expected.body, "utf8")}B <= ${FULL_BLOCK_MAX})`);
    assert.ok(
      line.anchors.includes(expected.start),
      `${CARD_REL} line ${line.at}: the block shown starts at ${RUNBOOK_REL}:${expected.start}, ` +
        `which the step line does not name (it names ${line.anchors.join(", ") || "nothing"}). ` +
        "The L-anchor is how a cycle finds the block in the runbook; an unnamed one is unreachable.",
    );
    assert.strictEqual(line.fence.lang, expected.lang, `${CARD_REL} line ${line.at}: fence language differs from ${RUNBOOK_REL}:${expected.start}`);
    assert.strictEqual(
      line.fence.body,
      expected.body,
      `${CARD_REL} line ${line.at}: the block is NOT byte-identical to ${RUNBOOK_REL}:${expected.start}. ` +
        "A card block a cycle runs must be the runbook's own bytes -- a paraphrased command is the " +
        "second-home defect check 13 exists to stop.",
    );
    shown++;
  }
  assert.ok(shown > 0, `${CARD_REL} shows no block in full at all -- the card would be a table of contents, not an executable digest`);
  return shown;
}

// (E) SES-297's position assertion, carried onto the card: the gate is FIRST because it IS first.
export function theGateLinePrecedesStepZero(card) {
  const gate = card.indexOf("\n**gate.** ");
  const zero = card.indexOf("\n**0.** ");
  assert.ok(gate > 0, `${CARD_REL} has no **gate.** line at all`);
  assert.ok(zero > 0, `${CARD_REL} has no **0.** line to order against`);
  assert.ok(
    gate < zero,
    `${CARD_REL} must put **gate.** before **0.** (gate@${gate}, zero@${zero}). Ordering IS the ` +
      "feature: the pre-boot gate is the first executable action of a cycle, and a card that lists " +
      "the bootstrap first teaches a cycle to pay for the clone before it asks whether to boot.",
  );
}

function controlsGoRed(card, md) {
  // (B) control -- a step the renderer has no NOTES entry for must stop the render, not be dropped.
  assert.throws(
    () => render(md + "\n**10. Nothing.**\n"),
    `control: a runbook step with no NOTES entry rendered anyway -- ${SCRIPT_REL} would silently omit steps`,
  );

  // (C) control -- one byte flipped inside a card block.
  const lines = card.split("\n");
  let flipped = null;
  outer: for (let i = 0; i < lines.length; i++) {
    if (!/^```/.test(lines[i])) continue;
    for (let j = i + 1; j < lines.length && !/^```\s*$/.test(lines[j]); j++) {
      if (!lines[j].length) continue;
      const copy = lines.slice();
      copy[j] = lines[j].slice(0, -1) + (lines[j].endsWith("X") ? "Y" : "X");
      flipped = copy.join("\n");
      break outer;
    }
  }
  assert.ok(flipped && flipped !== card, "control for (C) changed nothing (the SES-158 failure)");
  assert.throws(() => everyCardBlockIsTheRunbooksBytes(flipped, md), "control: a card block with one byte flipped still passed");

  // (E) control -- the gate line moved below the bootstrap line.
  const gateLine = lines.findIndex(l => l.startsWith("**gate.** "));
  const zeroLine = lines.findIndex(l => l.startsWith("**0.** "));
  assert.ok(gateLine >= 0 && zeroLine > gateLine, "control for (E): could not locate the two lines to swap");
  const swapped = lines.slice();
  swapped[gateLine] = lines[zeroLine];
  swapped[zeroLine] = lines[gateLine];
  const swappedCard = swapped.join("\n");
  assert.notStrictEqual(swappedCard, card, "control for (E) changed nothing (the SES-158 failure)");
  assert.throws(() => theGateLinePrecedesStepZero(swappedCard), "control: the gate below step 0 still passed");

  // (A) control -- the whole point. A hand-edit anywhere must not survive the equality check.
  assert.notStrictEqual(flipped, render(md), "control for (A): a mutated card still equals the render");
}

export function run() {
  const md = readLf(RUNBOOK_REL);
  const card = readLf(CARD_REL);
  const bytes = Buffer.byteLength(card, "utf8");

  // (A) The committed card IS the render. This is the exemption's whole justification.
  assert.strictEqual(
    card,
    render(md),
    `${CARD_REL} is not what ${RUNBOOK_REL} renders to. The runbook is the source and the card is ` +
      `the view -- never the reverse. Re-render it:  node ${SCRIPT_REL} --write`,
  );

  everyStepIsOnTheCard(card, md);                             // (B)
  const shown = everyCardBlockIsTheRunbooksBytes(card, md);   // (C)

  // (D) The size budget. Over the cap, lower FULL_BLOCK_MAX in the renderer -- never raise the cap.
  assert.ok(
    bytes >= CARD_MIN && bytes <= CARD_BYTE_CAP,
    `${CARD_REL} is ${bytes} bytes; it must sit in ${CARD_MIN}-${CARD_BYTE_CAP}. Under the floor it ` +
      "has stopped carrying the commands and is a table of contents; over the cap it has stopped " +
      `being a digest of a ${Buffer.byteLength(md, "utf8")}-byte runbook. Lower FULL_BLOCK_MAX, never raise the cap.`,
  );

  theGateLinePrecedesStepZero(card);                          // (E)

  // (F) The header names the runbook the card was rendered from, by content, not by date.
  const stamp = /sha256 ([0-9a-f]{16}) /.exec(card.split("\n")[0]);
  assert.ok(stamp, `${CARD_REL} line 1 must carry the source runbook's sha256`);
  assert.strictEqual(stamp[1], runbookSha(md), `${CARD_REL}'s header sha256 is not the current ${RUNBOOK_REL}'s -- the card was rendered from a different runbook`);

  // (G) check 13's exemption and this guard must name the SAME card, or one of them is protecting
  // a file the other does not hold.
  assert.ok(
    PROCEDURE_GENERATED_DOCS.has(CARD_REL),
    `scripts/check-session-docs.js's PROCEDURE_GENERATED_DOCS must carry ${CARD_REL}; it has ` +
      `${[...PROCEDURE_GENERATED_DOCS].join(", ") || "nothing"}. Without it check 13 FLAGs the card's ` +
      "copied blocks as a second home of the procedure; with it and without this test, they would be one.",
  );

  // (H) The CLI's check mode agrees, from a real process.
  const cli = spawnSync(process.execPath, [path.join(ROOT, SCRIPT_REL)], { cwd: ROOT, encoding: "utf8" });
  assert.strictEqual(cli.status, 0, `node ${SCRIPT_REL} exited ${cli.status} (expected 0)\n${cli.stdout}${cli.stderr}`);

  controlsGoRed(card, md);

  console.log(`  [PASS] ses-377-cycle-card.test.mjs`);
  console.log(`         ${CARD_REL} ${bytes}B (cap ${CARD_BYTE_CAP}) · ${parseSteps(md).length} steps · ${shown} blocks carried in full · ${RUNBOOK_REL} ${Buffer.byteLength(md, "utf8")}B sha256 ${runbookSha(md)} · CLI exit 0`);
}

selfRun(import.meta.url, run);
export default run;
